      Schema.Attribute.Private;
    dek: Schema.Attribute.Text;
    editions: Schema.Attribute.Relation<'oneToMany', 'api::edition.edition'>;
    gallery: Schema.Attribute.Media<'images', true>;
    kicker: Schema.Attribute.String;
    legacyHtml: Schema.Attribute.Text & Schema.Attribute.Private;
    legacyId: Schema.Attribute.Integer & Schema.Attribute.Private;
    legacyTitle: Schema.Attribute.String & Schema.Attribute.Private;
    locale: Schema.Attribute.String & Schema.Attribute.Private;
    localizations: Schema.Attribute.Relation<
      'oneToMany',
      'api::article.article'
    > &
      Schema.Attribute.Private;
    needsReview: Schema.Attribute.Boolean & Schema.Attribute.DefaultTo<false>;
    pageants: Schema.Attribute.Relation<'oneToMany', 'api::pageant.pageant'>;
    publishedAt: Schema.Attribute.DateTime;
    publishedOn: Schema.Attribute.Date & Schema.Attribute.Required;
    quote: Schema.Attribute.Component<'shared.quote', false>;
    relatedLinks: Schema.Attribute.Component<'shared.link', true>;
    section: Schema.Attribute.Enumeration<
      ['news', 'featured', 'opinions', 'specials', 'interviews']
